import { createContext, useContext, useEffect, useState } from "react";
import { Accordion, AccordionDetails, AccordionSummary, Alert, Box, Card, CardContent, Container, Divider, Grid, IconButton, ListItemButton, ListItemIcon, ListItemText, Typography } from '@mui/material';
import jsonData from '../data.json';
import caracData from '../carac.json';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { useTranslation } from 'react-i18next';
import CodexSelectionPopup from '../Components/CodexSelectionPopup';
import useOptionController from '../hooks/useOptionController';
import useCreateCarte from '../hooks/useCreateCarte';


// Fonction pour générer un ID unique
const generateUniqueId = () => {
    return `carte-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
};

export const MainContext = createContext({});

export default function MainProvider({ children }) {
    const codexList = jsonData;
    const caracJSON = caracData;
    const [selectedCodex, setSelectedCodex] = useState(null);
    const [selectedLogo, setSelectedLogo] = useState(null);
    const [selectedVersion, setSelectedVersion] = useState(null);
    const [selectedRare, setSelectedRare] = useState(null);
    const [selectedFaction, setSelectedFaction] = useState(null);
    const [formations, setFormations] = useState([]);
    const [selectedFormation, setSelectedFormation] = useState(null);
    const [cartes, setCartes] = useState([]);
    const [selectedCarteIndex, setSelectedCarteIndex] = useState(null);
    const [selectedFormationOptions, setSelectedFormationOptions] = useState(null);
    const [totalValue, setTotalValue] = useState(0);
    const [selectedCodexColor, setSelectedCodexColor] = useState('#9DA9B3'); // Couleur par défaut
    const [selectedCodexVersion, setSelectedCodexVersion] = useState(null);
    const [selectedCodexLogo, setSelectedCodexLogo] = useState('generique.png');
    const [selectedStrategie, setSelectedStrategie] = useState(null);
    const [selectedInitiative, setSelectedInitiative] = useState(null);
    const [isGamePageVisible, setIsGamePageVisible] = useState(false);
    const [isVersionPageVisible, setIsVersionPageVisible] = useState(false);
    const [isRulePageVisible, setIsRulePageVisible] = useState(false);
    const [showCodexSelection, setShowCodexSelection] = useState(true);
    const [open, setOpen] = useState(false);
    const [openChange, setOpenChange] = useState(false);
    const [carteIndex, setCarteIndex] = useState([]);
    const [handleInputChange, sethandleInputChange] = useState([]);
    let file = null;
    const [refs, setRefs] = useState([]);
    const [filteredData, setfilteredData] = useState([]);
    const [openPrintDialog, setOpenPrintDialog] = useState(false);
    const [printList, setPrintList] = useState(true);
    const [printCarac, setPrintCarac] = useState(false);
    const [openDrawer, setOpenDrawer] = useState(false);
    const [infos, setInfos] = useState([]);
    const [formattedInfos, setFormattedInfos] = useState(null);
    const [accordionStates, setAccordionStates] = useState(cartes.map(() => true));
    const [optionAlerte, setOptionAlerte] = useState(null);
    const [alertRare, setAlertRare] = useState(false);
    const [totalRareValue, setTotalRareValue] = useState(0);
    const [totalRareSpeValue, setTotalRareSpeValue] = useState(0);
    const cartesSansNbacti = cartes.filter(carte => carte.options.some(option => option.nbacti !== false));
    const { i18n, t } = useTranslation();
    const [selectedShowOptions, setSelectedShowOptions] = useState([]);

    //fonction pour fermer la page d'acceuil
    const handleCloseCodexSelection = () => {
        // Logique pour fermer la sélection de codex, si nécessaire
        setShowCodexSelection(false);
    };

    //fonction pour ouvrir la page d'acceuil
    const handleOpenCodexSelection = () => {
        setShowCodexSelection(true);
        setSelectedCodex(null);
        setSelectedFaction(null);
        setCartes([]); // Supprime toutes les cartes
        setSelectedCarteIndex(null); // Réinitialise la sélection
        setOpenChange(false);
        setSelectedFormation(null);
        setSelectedFormationOptions(null);
        setSelectedCodexColor('#9DA9B3');
        setIsRulePageVisible(false);

        handleToggleAllAccordions(true)

    };

    const handleClickOpenChange = () => {
        setOpenChange(true);
        setIsGamePageVisible(false);
    };

    const handleCloseChange = () => {
        setOpenChange(false);
    };

    // Fonction pour regrouper les codex par catégorie
    function groupCodexByCategory(jsonData) {
        const groupedCodex = {};
        // Parcourir chaque codex et les regrouper par catégorie
        jsonData.forEach((codex) => {
            const category = codex.categorie;
            if (!groupedCodex[category]) {
                groupedCodex[category] = [];
            }
            groupedCodex[category].push(codex);
        });
        return groupedCodex;
    }
    // Fonction pour faire défiler vers une section spécifique
    function scrollToSection() {
        // Utilisez la fonction scrollTo pour déplacer la vue vers la section cible
        if (window.innerWidth <= 768) {
            document.getElementById('options').scrollIntoView({
                behavior: 'smooth' // Ajoute un effet de défilement fluide
            });
        }
    }

    //fonction pour récupérer le codex de la page d'accueil
    const handleSelectCodex = (codex) => {
        setShowCodexSelection(false);
        const selectedCodex = codex.codex;
        setSelectedCodex(selectedCodex);
        const selectedLogo = codex.logo;
        setSelectedLogo(selectedLogo);
        const selectedRare = codex.codexRare;
        setSelectedRare(selectedRare);
        const selectedFaction = codex.faction;
        setSelectedFaction(selectedFaction);
        const selectedVersion = codex.version;
        setSelectedVersion(selectedVersion);
        const selectedStrategie = codex.strategie;
        setSelectedStrategie(selectedStrategie);;
        const selectedInitiative = codex.initiative;
        setSelectedInitiative(selectedInitiative)

        // Filtrer les formations en fonction du codex sélectionné

        const selectedCodexData = codexList.find((codex) => codex.codex === selectedCodex);
        if (selectedCodexData) {
            setSelectedCodexVersion(selectedCodexData.version);
            setSelectedCodexLogo(selectedCodexData.logo);
            setSelectedCodexColor(selectedCodexData.color || '#9da9b3'); // Utilisez la couleur du codex ou la couleur par défaut

            const allFormationsByGroups = selectedCodexData.groupes.map((groupe) => ({
                groupName: groupe.name,
                formations: groupe.formation,
                detail: groupe.detail,
            }));
            setFormations(allFormationsByGroups);
            setSelectedFormation(null); // Réinitialisez la sélection de la formation
        } else {
            setFormations([]);
            setSelectedFormation(null);
        }
    };

    //création d'une CARTE + CONTROLE FORMATION////////
    // On appele le fichier usecreatecarte.js
    const { handleCreateCarte } = useCreateCarte({
        jsonData,
        selectedCodex,
        cartes,
        setCartes,
        setAccordionStates,
        setOptionAlerte,
        t,
        setFormations,
        setSelectedCodexVersion,
        setSelectedCodexLogo,
        setSelectedCodexColor,
        setSelectedCarteIndex
    });

    // Ajout d'une OPTION + CONTROLE OPTION////////
    // On appele le fichier useOptionController.js
    const { handleOptionSelect } = useOptionController({
        cartes,
        setCartes,
        setOptionAlerte,
        t
    });

    //suppression carte
    const handleRemoveCarte = (index) => {
        const updatedCartes = [...cartes];
        updatedCartes.splice(index, 1);
        setCartes(updatedCartes);
    };

    // Fonction pour gérer la sélection d'une carte
    const handleCarteSelect = (carteIndex) => {
        setSelectedCarteIndex(carteIndex);
    };

    // Afficher les options disponibles lorsque la carte est sélectionnée
    const selectedCarte = selectedCarteIndex !== null ? cartes[selectedCarteIndex] : null;
    //Soit on appel cette fonction qui créer la carte et charge les options
    const handleFormationAndCreateCarte = (formation) => {
        setSelectedFormation(formation);
        handleCreateCarte(formation);
        handleShowOptions(formation);
    };
    //Soit on appel cette fonction charge juste les options. Pas de carte, donc pas de selection possible
    const handleShowOptions = (formation) => {

        const options = formation.options.map((option) => ({
            ...option,
            selectedValue: 0, // 0 for options without max selectedValue: option.max ? 1 : 0,
        }));
        setSelectedShowOptions(options);
        setSelectedFormationOptions(options);
    };

    //quand on clique sur le nom d'une formation on ne voit que le option - a modifier a terme
    const handleShowFormationOptions = (optionbase) => {
        setSelectedFormationOptions(optionbase);
    };

    //a chaque fois qu'une carte est mise a jour, on vérifie que les points d'option rares n'est pas depassé
    // les logique de calcul sont dans calcUtils.js
    useEffect(() => {
        const rareValue = calculateTotalRareValue(cartes);
        const totaleCarteValue = calculateTotalValue(cartes);
        const totalCarteOptionRare = calculateTotalOptionRareValue(cartes);
        const rareSpeValue = calculateTotalRareSpeValue(cartes);

        setTotalRareValue(rareValue + totalCarteOptionRare);

        const limit = Math.ceil((selectedRare || 0) * totaleCarteValue);
        if (rareSpeValue > limit || (rareValue + totalCarteOptionRare) > limit) {
            setAlertRare(true);
        } else {
            setAlertRare(false);
        }
    }, [cartes, selectedRare]);


    const AlerteAutoClose = ({ message }) => {
        // Page d'accueil des messages d'alerte
        useEffect(() => {
            const timer = setTimeout(() => {
                setOptionAlerte(null);
            }, 3000);

            return () => {
                clearTimeout(timer);
            };
        }, []);

        return (
            <div>
                {optionAlerte && (
                    <Alert severity="error">
                        {optionAlerte}
                    </Alert>
                )}
            </div>);
    };

    const handleOptionRemove = (option, carteIndex) => {

        const updatedCartes = [...cartes];
        const options = updatedCartes[carteIndex].options;
        const optionIndex = options.findIndex((opt) => opt.name === option.name);
        if (optionIndex !== -1) {
            options.splice(optionIndex, 1);
            setCartes(updatedCartes);
            // Mettez à jour le total ici
            setTotalValue(calculateTotalValue());
        }

    };

    const handleRemoveAllCartes = () => {
        setCartes([]); // Supprime toutes les cartes
        setSelectedCarteIndex(null); // Réinitialise la sélection
        setOpen(false);
    };

    const handleClickOpen = () => {
        setOpen(true);
    };

    const handleClose = () => {
        setOpen(false);
    };

    /////////////CALCULE///////////
    // calcule de la valeur d'une carte en faisant la somme des valeur X le nombre, sauf pour les options Single
    const calculateCarteValue = (carte) => {
        let sum = 0;
        if (carte.options) {
            carte.options.forEach((option) => {
                if (option.valueSingle) {
                    sum += option.value;
                } else {
                    sum += option.value * option.selectedValue;
                }
            });
        }
        return sum;
    };

    //Fait la somme de toutes les valeurs des cartes
    const calculateTotalValue = () => {
        let sum = 0;
        cartes.forEach((carte) => {
            sum += calculateCarteValue(carte);
        });
        return sum;
    };

    //Calcul de la valeur des formations rares
    const calculateTotalRareValue = (cartes) => {
        return cartes.reduce((total, carte) => {
            if (carte && (carte.rare)) {
                return total + calculateCarteValue(carte);
            }
            return total;
        }, 0);
    };

    //Calcul de la valeur des formations rares special pour les tyty
    const calculateTotalRareSpeValue = (cartes) => {
        return cartes.reduce((totale, carte) => {
            if (carte && (carte.rarespe)) {
                return totale + calculateCarteValue(carte);
            }
            return totale;
        }, 0);
    };

    // Calcul de la valeur totale des options rares type dominatrix
    const calculateTotalOptionRareValue = (cartes) => {
        return cartes.reduce((total, carte) => {
            // Vérifiez si la carte a des options
            if (carte.options && carte.options.length > 0) {
                // Sommez la valeur de chaque option rare
                const valeurOptionsRares = carte.options.filter(option => option.rare).reduce((sum, option) => sum + option.value, 0);
                return total + valeurOptionsRares;
            }
            return total;
        }, 0);
    };

    const maxCarte = cartes.reduce((prev, current) => {
        return calculateCarteValue(current) > calculateCarteValue(prev) ? current : prev;
    }, {});
    /////////////////////////////////////////////
    ///////////FIN CALCULE/////////////////////

    const handlePrint = () => {
        getAllSelectedRefs(); // Appeler la fonction pour obtenir les références sélectionnées
        // Attendre un court délai avant d'imprimer (pour permettre à getAllSelectedRefs de s'exécuter)
        setTimeout(() => {
            window.print(); // Appeler la fonction d'impression
        }, 500); // Ajuste le délai selon tes besoins (en millisecondes)
    };

    //Export des cartes
    const exportAllCartes = () => {
        const codexName = selectedCodex || 'UnknownCodex';
        const codexFaction = selectedFaction || 'UnknownCodex';
        const codexLogo = selectedLogo || 'generique.png';
        const points = totalValue || 0;
        const color = selectedCodexColor || '#9DA9B3';
        const version = selectedCodexVersion || 'UnknownVersion';
        const allCartes = {
            codexReference: codexName, // Ajouter une référence au codex
            codexFaction: codexFaction,
            codexLogo: codexLogo,
            points: points,
            color: color,
            version: version,
            cartes: cartes
        };
        // Convertir l'objet allCartes en chaîne JSON
        const jsonData = JSON.stringify(allCartes, null, 2);

        // Créer un objet Blob à partir des données JSON
        const blob = new Blob([jsonData], { type: 'application/json' });
        // Générer un URL pour télécharger le fichier JSON
        const url = URL.createObjectURL(blob);

        // Créer un élément d'ancre pour le téléchargement
        const link = document.createElement('a');
        link.href = url;
        link.download = `liste_${selectedCodex}_${calculateTotalValue()}pts.json`;

        // Simuler un clic sur le lien pour télécharger le fichier
        document.body.appendChild(link);
        link.click();

        // Nettoyer après le téléchargement
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    // import liste
    const importCartesFromJSON = (file) => {
        const reader = new FileReader();
        reader.readAsText(file);
        reader.onload = (event) => {
            try {
                const importedData = JSON.parse(event.target.result);

                // Récupérer les données du fichier importé
                const importedCodexReference = importedData.codexReference; // Référence au codex
                const importedCartes = importedData.cartes; // Données des cartes
                const importedColor = importedData.color; // Couleur du codex
                const importedFaction = importedData.codexFaction; // Faction du codex
                const importedLogo = importedData.codexLogo; // Logo du codex
                const importedVersion = importedData.version; // Logo du codex                 

                // Mettre à jour selectedCodex avec la référence du fichier importé
                setSelectedCodex(importedCodexReference);
                setSelectedFaction(importedFaction);
                setSelectedLogo(importedLogo);
                setSelectedVersion(importedVersion);
                //cacher la popUp
                setShowCodexSelection(false);
                setSelectedFormationOptions(null);

                handleToggleAllAccordions(true)

                const selectedCodexData = codexList.find((codex) => codex.codex === importedCodexReference);
                if (selectedCodexData) {
                    setSelectedCodexLogo(selectedCodexData.logo);
                    setSelectedRare(selectedCodexData.codexRare);
                    setSelectedCodexColor(selectedCodexData.color || '#9da9b3'); // Utilisez la couleur du codex ou la couleur par défaut
                    const allFormationsByGroups = selectedCodexData.groupes.map((groupe) => ({
                        groupName: groupe.name,
                        formations: groupe.formation,
                        detail: groupe.detail,
                    }));
                    setFormations(allFormationsByGroups);
                    setSelectedFormation(null);

                } else {
                    setFormations([]);
                    setSelectedFormation(null);
                }

                // Ajouter des IDs uniques aux cartes importées si elles n'en ont pas
                const cartesWithIds = importedCartes.map(carte => ({
                    ...carte,
                    id: carte.id || generateUniqueId()
                }));
                setCartes(cartesWithIds);

            } catch (error) {
                console.error('Error importing file :', error);
            }
        };
    };

    const handleFileChange = (event) => {
        setSelectedCodex('');
        setSelectedFaction('');
        setFormations([]);
        setCartes([]);
        setSelectedCarteIndex(null);
        if (file !== null) {
            file = null; // Réinitialiser le fichier s'il existe déjà
        }

        const newFile = event.target.files[0]; // Nouveau fichier à charger

        if (newFile) {
            file = newFile; // Affecter le nouveau fichier à la variable file
            importCartesFromJSON(file);
        }
        // Réinitialiser l'élément input de type file
        event.target.value = null;
    };

    // Fonction pour obtenir les références uniques des options sélectionnées
    const getAllSelectedRefs = () => {
        setRefs([]);
        const references = new Set(); // Utilisation de Set pour stocker des valeurs uniques

        cartes.forEach(carte => { // Parcours de chaque carte
            if (Array.isArray(carte.ref)) { // Vérifie si la référence est un tableau
                carte.ref.forEach(subRef => { // Parcours chaque élément du tableau
                    if (subRef !== undefined) { // Ajoute l'élément au Set 'references' si ce n'est pas undefined
                        references.add(subRef);
                    }
                });
            } else if (carte.ref !== undefined) { // Ajoute la référence au Set 'references' si ce n'est pas undefined
                references.add(carte.ref);
            }

            carte.options.forEach(option => { // Parcours chaque option dans la carte
                if (option.selectedValue > 0) { // Vérifie si l'option est sélectionnée
                    if (Array.isArray(option.ref)) { // Vérifie si la référence est un tableau
                        option.ref.forEach(subRef => { // Parcours chaque élément du tableau
                            if (subRef !== undefined) { // Ajoute l'élément au Set 'references' si ce n'est pas undefined
                                references.add(subRef);
                            }
                        });
                    } else if (option.ref !== undefined) { // Ajoute la référence au Set 'references' si ce n'est pas undefined
                        references.add(option.ref);
                    }
                }
            });
        });

        const referencesArray = [...references]; // Convertit le Set en tableau
        const filteredReferences = referencesArray.filter(ref => ref !== undefined); // Filtre les undefined du tableau

        setRefs(filteredReferences); // Met à jour l'état ou la variable 'refs' sans les undefined
        return filteredReferences; // Renvoie le tableau filtré
    };

    useEffect(() => { filterData() }, [refs]); // mets a jour filtereddata a chaque fois que refs change

    // focntion pour mettre en forme les options présente dans la liste
    const filterData = () => {
        if (selectedFaction && refs) {
            const filteredByCodex = caracJSON.filter(item => item.faction === selectedFaction);
            const filtered = [];
            filteredByCodex.forEach(item => {
                item.stat.forEach(stat => {
                    if (refs.includes(stat.Nom)) {
                        filtered.push({
                            Nom: stat.Nom,
                            Type: stat.Type,
                            Rang: stat.rang,
                            Vitesse: stat.Vitesse,
                            Blindage: stat.Blindage,
                            CC: stat.CC,
                            FF: stat.FF,
                            Notes: stat.Notes,
                            armes: stat.armes.map(arme => `${arme.Arme} - ${arme.Portée} - ${arme['Puissance de feu']}`),
                        });
                    }
                });
            });
            filtered.sort((a, b) => a.Rang - b.Rang);
            setfilteredData(filtered);
        }
    };

    //Fonction pour recupérer les caract de l'option selectionné
    function getInfoByOption(option) {
        if (option && option.ref && caracJSON) {
            const infos = [];
            // Filtrer caracJSON par faction
            const filteredCaracJSON = caracJSON.filter(item => item.faction === selectedFaction);
            const matchingStats = filteredCaracJSON.filter(item => {
                const matchingRefs = item.stat.filter(stat => {
                    // Si la propriété ref est un tableau, on vérifie si l'option.ref est inclus
                    if (Array.isArray(option.ref)) {
                        return option.ref.includes(stat.Nom);
                    } else {
                        return stat.Nom === option.ref;
                    }
                });
                return matchingRefs.length > 0;
            });
            matchingStats.forEach(matchingStat => {
                matchingStat.stat.forEach(stat => {
                    // Si la propriété ref est un tableau, on vérifie si l'option.ref est inclus
                    if (Array.isArray(option.ref) && option.ref.includes(stat.Nom)) {
                        const info = {
                            Nom: stat.Nom,
                            Type: stat.Type,
                            Rang: stat.rang,
                            Vitesse: stat.Vitesse,
                            Blindage: stat.Blindage,
                            CC: stat.CC,
                            FF: stat.FF,
                            Notes: stat.Notes,
                            armes: stat.armes.map(arme => `${arme.Arme} - ${arme.Portée} - ${arme['Puissance de feu']}`),
                        };
                        infos.push(info);
                    } else if (!Array.isArray(option.ref) && stat.Nom === option.ref) {
                        // Si la propriété ref est une chaîne simple, on vérifie l'égalité
                        const info = {
                            Nom: stat.Nom,
                            Type: stat.Type,
                            Rang: stat.rang,
                            Vitesse: stat.Vitesse,
                            Blindage: stat.Blindage,
                            CC: stat.CC,
                            FF: stat.FF,
                            Notes: stat.Notes,
                            armes: stat.armes.map(arme => `${arme.Arme} - ${arme.Portée} - ${arme['Puissance de feu']}`),
                        };
                        infos.push(info);
                    }
                });
            });

            return infos;
        } else {
            return [];
        }
    };
    ///////////////////////
    ///////////////////////Fonction pour Mettre en forme les caract de l'option selectionné
    function formattedContent(infos) {
        return (
            <Box style={{ backgroundColor: '#e5e5e5' }}>
                {infos.map((row, index) => (
                    <Grid container item key={index} alignItems={'center'} >
                        <Grid item xs={10} style={{ borderTop: 1, backgroundColor: '#838383' }}>
                            <Typography variant='body2' color={'white'}><b>{row.Nom}</b></Typography>
                        </Grid>
                        <Grid item xs={1} style={{ borderTop: 1, backgroundColor: '#838383' }}>
                            <Typography variant='body2' color={'white'}><b>{row.Type}</b></Typography>
                        </Grid>
                        <Grid item xs={1}
                            container
                            justifyContent="center"  // Centre horizontalement
                            alignItems="center"      // Centre verticalement
                            style={{ borderTop: 1, backgroundColor: '#838383' }}>
                            <img
                                src={process.env.PUBLIC_URL + '/' + row.Type + '.png'}
                                alt="Logo"
                                style={{
                                    height: '20px',
                                    objectFit: 'contain' // Garde les proportions de l'image
                                }}
                            /></Grid>

                        <Grid item xs={2}>
                            <Typography variant='caption'>{t('stats.speed')}</Typography>
                        </Grid>
                        <Grid item xs={1}>
                            <Typography variant='caption'>{t('stats.armor')}</Typography>
                        </Grid>
                        <Grid item xs={1}>
                            <Typography variant='caption'>{t('stats.cc')}</Typography>
                        </Grid>
                        <Grid item xs={1}>
                            <Typography variant='caption'>{t('stats.ff')}</Typography>
                        </Grid>
                        <Grid item xs={7} >
                            <Typography variant='caption' >{t('stats.weapon')}</Typography>
                        </Grid>


                        <Grid item xs={2}>
                            <Typography variant='caption'>{row.Vitesse}</Typography>
                        </Grid>
                        <Grid item xs={1}>
                            <Typography variant='caption'>{row.Blindage}</Typography>
                        </Grid>
                        <Grid item xs={1}>
                            <Typography variant='caption'>{row.CC}</Typography>
                        </Grid>
                        <Grid item xs={1}>
                            <Typography variant='caption'>{row.FF}</Typography>
                        </Grid>
                        <Grid item xs={7}>
                            <Grid Container alignContent={'center'}>
                                {row.armes.map((arme, idx) => (
                                    <Grid item xs={12} key={idx}>
                                        <Typography key={idx} variant='caption' sx={{ fontSize: '8pt' }}>
                                            {arme}
                                        </Typography>
                                    </Grid>
                                ))}
                            </Grid>
                        </Grid>
                        <Grid item xs={12} >
                            <Typography variant='caption' sx={{ fontSize: '8pt', lineHeight: 1.1, margin: 1, padding: 0.5 }} >
                                {row.Notes}
                            </Typography>
                        </Grid>
                    </Grid>
                ))}

            </Box >
        );
    };

    // Fonction pour mettre à jour les informations en fonction de l'option sélectionnée
    const updateInfos = (option) => {
        // Obtenez les informations brutes
        const rawInfos = getInfoByOption(option);
        // Mettez à jour l'état des informations brutes
        setInfos(rawInfos);
        // Formatez les informations dans la boîte
        const content = formattedContent(rawInfos);
        // Mettez à jour l'état avec le contenu formaté
        setFormattedInfos(content);
    };

    const displayPrintValue = printList ? 'Block' : 'none';
    const displayCaracValue = printCarac ? 'Block' : 'none';

    const handleOpenPrintDialog = () => {
        setOpenPrintDialog(true);
    };

    const handleClosePrintDialog = () => {
        setOpenPrintDialog(false);
    };

    const handlePrintListChange = (event) => {
        setPrintList(event.target.checked);
    };

    const handlePrintCaracChange = (event) => {
        setPrintCarac(event.target.checked);
    };

    const handleDrawerOpen = () => {
        setOpenDrawer(true);
    };

    const handleDrawerClose = () => {
        setOpenDrawer(false);
    };

    // Fonction de contrôle des références pour les caracts
    const checkReferences = () => {
        const missingReferences = [];

        // Parcourez chaque faction dans data.json
        codexList.forEach((codex) => {
            const faction = codex.faction;

            // Obtenez la liste des références dans data.json pour cette faction
            const dataReferences = codex.groupes.flatMap((groupe) =>
                groupe.formation.flatMap((formation) =>
                    formation.options.flatMap((option) => (option.ref ? option.ref : []))
                )
            );

            // Obtenez la liste des noms dans carac.json pour cette faction
            const caracNames = caracJSON
                .filter((item) => item.faction === faction)
                .flatMap((item) => item.stat.map((stat) => stat.Nom));

            // Recherchez les références manquantes
            dataReferences.forEach((ref) => {
                if (!caracNames.includes(ref)) {
                    missingReferences.push({ faction, ref });
                }
            });
        });

        // Affichez les références manquantes dans la console
        console.log('Références manquantes :', missingReferences);
    };

    // Appel de la fonction lors du chargement de la page
    window.onload = checkReferences;

    const CopyText = () => {
        const { selectedCodex, calculateTotalValue, cartes, maxCarte } = useContext(MainContext);
        const [isCopied, setIsCopied] = useState(false);

        const handleCopyToClipboard = () => {
            const contentToCopy =
                `## Liste ${selectedCodex} ${calculateTotalValue()} pts \r Nombre de formations ***${cartes.length}*** \r ***BLM : ${maxCarte.formation} ${calculateCarteValue(maxCarte)} pts***
                ${cartes.map((carte, carteIndex) => (
                    `
                - ***${carte.formation} - ${calculateCarteValue(carte)}*** 
                ${carte.options.map((option, optionIndex) => {
                        const quantityString = option.selectedValue > 1 ? `${option.selectedValue} ` : '';
                        return ` - ${quantityString}${option.name} - ${option.value * option.selectedValue}\r`;
                    }).join('')}
              `
                )).join('')
                }
                `;

            navigator.clipboard.writeText(contentToCopy)
                .then(() => {
                    setIsCopied(true);
                    setTimeout(() => {
                        setIsCopied(false);
                    }, 2000);
                })
                .catch((error) => {
                    console.error('Erreur lors de la copie dans le presse-papiers :', error);
                });
        };

        return (
            <ListItemButton>
                <ListItemIcon onClick={handleCopyToClipboard} >
                    <IconButton>
                        <ContentCopyIcon />
                        {isCopied ? 'Copié !' : ''}
                    </IconButton>
                </ListItemIcon>
                <ListItemText primary={t('copy_discord')} onClick={handleCopyToClipboard} />
            </ListItemButton>
        );
    };

    //copy pour export ELO
    const CopyEloList = () => {
        const { selectedCodex, calculateTotalValue, cartes, maxCarte } = useContext(MainContext);
        const [isCopied, setIsCopied] = useState(false);

        const handleCopyEloToClipboard = () => {
            const contentToCopy = `
Liste : ${selectedCodex} - ${calculateTotalValue()} pts
Nombre de formations: ${cartes.length}
BLM: ${maxCarte.formation} - ${calculateCarteValue(maxCarte)} pts

${cartes.map(carte => {
                return `- ${carte.formation} - ${calculateCarteValue(carte)} pts
${carte.options.map(option => {
                    const quantityString = option.selectedValue > 1 ? `${option.selectedValue} x ` : '';
                    return `  - ${quantityString}${option.name} - ${option.value * option.selectedValue} pts`;
                }).join('\n')}
`;
            }).join('\n')}
`;
            navigator.clipboard.writeText(contentToCopy)
                .then(() => {
                    setIsCopied(true);
                    setTimeout(() => setIsCopied(false), 2000);
                })
                .catch(error => {
                    console.error('Erreur lors de la copie dans le presse-papiers :', error);
                });
        };

        return (
            <ListItemButton>
                <ListItemIcon>
                    <IconButton onClick={handleCopyEloToClipboard}>
                        <ContentCopyIcon />
                        {isCopied && 'Copié !'}
                    </IconButton>
                </ListItemIcon>
                <ListItemText primary={t('copy_elo')} onClick={handleCopyEloToClipboard} />
            </ListItemButton>
        );
    };

    //Etat pour tout les accordeon
    const handleToggleAllAccordions = (value) => {
        setAccordionStates(Array(cartes.length).fill(value));
    };

    //pour controler l'etat de chaque accordeons
    const handleToggleAccordion = (index) => {
        setAccordionStates((prevStates) => {
            const newStates = [...prevStates];
            newStates[index] = !newStates[index];
            return newStates;
        });
    };

    //pour afficher la gamepage et cacher les autres
    const handleToggleGameMode = () => {
        setIsGamePageVisible(!isGamePageVisible);
    };

    // Affiche la page de versions
    const handleVersionClick = () => {
        setIsVersionPageVisible(true);
    };

    // Affiche la page de des regles
    const handleRuleClick = () => {
        setIsRulePageVisible(!isRulePageVisible);
        setIsVersionPageVisible(false);
        setIsGamePageVisible(false);
    };


    ////////////////////////////////////////////////
    //// pour la gestion de la modale des optionref
    const [modalOpen, setModalOpen] = useState(false);
    const [modalOptions, setModalOptions] = useState([]); // Contient les options à afficher dans la modale
    const [tempSelections, setTempSelections] = useState({}); // Stocke les modifications temporaires
    const [modalMainOption, setModalMainOption] = useState(null); // Option principale
    const [remainingOptions, setRemainingOptions] = useState(null);

    const openModal = (mainOption, options) => {
        if (!Array.isArray(options)) {
            console.error("Les options ne sont pas un tableau :", options);
            return;
        }

        // Filtrer les options où `refoption` ou `tagrefoption` correspond à `mainOption.tagrefoption`
        const filteredOptions = options.filter(
            (opt) =>
                opt.refoption === mainOption.tagrefoptions ||
                opt.tagrefoption === mainOption.tagrefoptions
        );
        setModalMainOption(mainOption);
        setModalOptions(filteredOptions);
        setRemainingOptions(mainOption.nbrefoptions);

        const initialSelections = {};
        options.forEach((opt) => {
            initialSelections[opt.name] = 0;
        });

        if (mainOption.min !== undefined && mainOption.max !== undefined) {
            initialSelections[mainOption.name] = mainOption.selectedValue || mainOption.min || 0;

        } else {

            initialSelections[mainOption.name] = mainOption.selectedValue || 1;
        }

        setTempSelections(initialSelections);
        setModalOpen(true);
    };

    const handleSelectionChange = (optionName, value) => {
        const newSelections = {
            ...tempSelections,
            [optionName]: value,
        };

        // Calcul du total des options secondaires
        const totalSelected = Object.keys(newSelections)
            .filter((name) => name !== modalMainOption.name) // Exclure l'option principale
            .reduce((sum, name) => sum + parseInt(newSelections[name] || 0, 10), 0);
        const updatedRemainingOptions = modalMainOption.nbrefoptions - totalSelected;
        if (modalMainOption.nbrefoptions === 0) {
            setRemainingOptions(0)
        }
        else {
            setRemainingOptions(updatedRemainingOptions); // Mise à jour du compteur restant
        }
        setTempSelections(newSelections); // Mise à jour des sélections
    };

    const handleMainOptionChange = (value) => {
        const updatedMainOption = {
            ...modalMainOption,
            nbrefoptions: value,

        };
        // Calcul du total des options secondaires sélectionnées
        const totalSecondaryOptions = Object.keys(tempSelections)
            .filter((name) => name !== updatedMainOption.name) // Exclure l'option principale
            .reduce((sum, name) => sum + parseInt(tempSelections[name] || 0, 10), 0);

        // Mise à jour de `remainingOptions` en fonction du nouveau `selectedValue`
        const updatedRemainingOptions = value - totalSecondaryOptions;

        // Validation : si le total dépasse la limite, ne pas appliquer le changement
        if (updatedRemainingOptions < 0) {
            alert(t('more_secondary_option'));
            return;
        }

        // Mettre à jour l'état
        setModalMainOption(updatedMainOption); // Met à jour `modalMainOption`
        setRemainingOptions(updatedRemainingOptions); // Met à jour les options restantes
        setTempSelections((prevSelections) => ({
            ...prevSelections,
            [updatedMainOption.name]: value,
        }));
    };

    const validateModalSelections = () => {
        if (!modalMainOption) {
            console.error("Option principale non trouvée !");
            return;
        }

        const selectedMainValue = tempSelections[modalMainOption.name];
        if (selectedMainValue === undefined) {
            alert(t('alert.select_main_option'));
            return;
        }

        // Vérification finale des options secondaires
        const totalSecondaryOptions = Object.keys(tempSelections)
            .filter((name) => name !== modalMainOption.name)
            .reduce((sum, name) => sum + parseInt(tempSelections[name] || 0, 10), 0);

        if (totalSecondaryOptions > modalMainOption.nbrefoptions && modalMainOption.nbrefoptions != 0) {
            alert(t('alert.secondary_options_limit_exceeded'));
            return;
        }

        const updatedMainOption = {
            ...modalMainOption,
            selectedValue: selectedMainValue,
        };

        const updatedOptions = modalOptions
            .map((opt) => {
                const selectedValue = tempSelections[opt.name];
                return selectedValue > 0 ? { ...opt, selectedValue } : null;
            })
            .filter(Boolean);

        handleOptionSelect(updatedMainOption, selectedCarteIndex, updatedMainOption.selectedValue);
        updatedOptions.forEach((opt) => {
            handleOptionSelect(opt, selectedCarteIndex, opt.selectedValue);
        });

        setModalOpen(false); // Fermer la modale
    };





    return (
        <MainContext.Provider
            value={
                {
                    scrollToSection,
                    selectedCodexLogo,
                    cartesSansNbacti,
                    totalRareValue, totalRareSpeValue,
                    optionAlerte,
                    alertRare,
                    AlerteAutoClose,
                    handleToggleAccordion,
                    setAccordionStates,
                    accordionStates,
                    handleToggleAllAccordions,
                    formattedInfos,
                    infos,
                    updateInfos,
                    CopyText,
                    CopyEloList,
                    handleDrawerOpen, openDrawer,
                    handleDrawerClose,
                    displayCaracValue,
                    displayPrintValue,
                    handleOpenPrintDialog,
                    handleClosePrintDialog,
                    openPrintDialog,
                    refs,
                    filterData,
                    filteredData,
                    getAllSelectedRefs,
                    exportAllCartes,
                    handleInputChange,
                    handleFileChange,
                    selectedCodexColor,
                    selectedCarte,
                    selectedCodex,
                    selectedLogo,
                    selectedCodexVersion,
                    selectedFormation,
                    selectedFormationOptions,
                    selectedShowOptions,
                    selectedCarteIndex,
                    maxCarte,
                    handleOptionRemove,
                    handleRemoveCarte,
                    handleShowFormationOptions,
                    handleCarteSelect,
                    handleSelectCodex,
                    handleRemoveAllCartes,
                    handleOptionSelect,
                    handleFormationAndCreateCarte,
                    handleShowOptions,
                    handleOpenCodexSelection,
                    formations,
                    selectedFaction,
                    showCodexSelection,
                    CodexSelectionPopup,
                    handleCloseCodexSelection,
                    codexList,
                    calculateTotalValue,
                    calculateCarteValue,
                    jsonData,
                    handlePrint,
                    open,
                    handleClickOpen,
                    handleClose,
                    openChange,
                    handleClickOpenChange,
                    handleCloseChange,
                    carteIndex,
                    printCarac,
                    printList,
                    handlePrintCaracChange,
                    handlePrintListChange,
                    handleToggleGameMode,
                    isGamePageVisible,
                    selectedVersion,
                    cartes,
                    setCartes,
                    calculateTotalOptionRareValue,
                    totalValue,
                    selectedStrategie,
                    selectedInitiative,
                    modalOpen,
                    setModalOpen,
                    modalMainOption,
                    handleMainOptionChange,
                    remainingOptions,
                    modalOptions,
                    tempSelections,
                    handleSelectionChange,
                    validateModalSelections,
                    openModal,
                    handleVersionClick,
                    setIsVersionPageVisible,
                    isVersionPageVisible,
                    isRulePageVisible,
                    setIsRulePageVisible,
                    handleRuleClick,
                    handleOpenCodexSelection,
                    handleCloseCodexSelection,
                    handleSelectCodex,
                    codexList,
                }}>
            {/* Affiche la popup d'accueil au niveau du provider */}
            {showCodexSelection && (
                <CodexSelectionPopup
                    codexList={codexList}
                    onSelectCodex={handleSelectCodex}
                    onClose={handleCloseCodexSelection}
                />
            )}
            {children}
        </MainContext.Provider>
    )
}