import React, { useContext, useEffect, useState } from "react";
import { Container, Typography, Accordion, AccordionSummary, AccordionDetails, Chip, Box, Card, CardContent } from "@mui/material";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import changelogData from "../changelog.json";
import { MainContext } from '../Contexts/MainContext';
import rules from '../rules.json';

export default function RulePage() {
    // États pour les mots-clés sélectionnés par catégorie
    const [selectedKwTable, setSelectedKwTable] = useState([]);
    const [selectedKwGenerique, setSelectedKwGenerique] = useState([]);
    const [selectedKwPhase, setSelectedKwPhase] = useState([]);
    const [selectedKwUnite, setSelectedKwUnite] = useState([]);
    const [selectedKwSpeciale, setSelectedKwSpeciale] = useState([]);

    const { isRulePageVisible, isGamePageVisible, isVersionPageVisible } = useContext(MainContext);

    // Fonction générique pour gérer la sélection/désélection
    const handleChipClick = (group, keyword) => {
        const setters = {
            kwtable: setSelectedKwTable,
            kwgenerique: setSelectedKwGenerique,
            kwphase: setSelectedKwPhase,
            kwunite: setSelectedKwUnite,
            kwspeciale: setSelectedKwSpeciale,
        };

        const selectedKeywords = {
            kwtable: selectedKwTable,
            kwgenerique: selectedKwGenerique,
            kwphase: selectedKwPhase,
            kwunite: selectedKwUnite,
            kwspeciale: selectedKwSpeciale,
        }[group];

        const updatedKeywords = selectedKeywords.includes(keyword)
            ? selectedKeywords.filter((key) => key !== keyword)
            : [...selectedKeywords, keyword];

        setters[group](updatedKeywords);
    };

    // Fonction de filtrage combiné
    const allSelectedKeywords = [
        ...selectedKwTable,
        ...selectedKwGenerique,
        ...selectedKwPhase,
        ...selectedKwUnite,
        ...selectedKwSpeciale,
    ];

    const filteredRules = allSelectedKeywords.length
        ? rules.filter((rule) =>
            allSelectedKeywords.every((keyword) =>
                [...(rule.kwtable || []), ...(rule.kwgenerique || []), ...(rule.kwphase || []), ...(rule.kwunite || []), ...(rule.kwspeciale || [])].includes(keyword)
            )
        )
        : rules;

    const extractUniqueKeywords = (category) => {
        return Array.from(
            new Set(rules.flatMap((rule) => rule[category] || []))
        ).filter(Boolean).sort((a, b) => a.localeCompare(b, "fr"));
    };

    const uniqueKwTable = extractUniqueKeywords('kwtable');
    const uniqueKwGenerique = extractUniqueKeywords('kwgenerique');
    const uniqueKwPhase = extractUniqueKeywords('kwphase');
    const uniqueKwUnite = extractUniqueKeywords('kwunite');
    const uniqueKwSpeciale = extractUniqueKeywords('kwspeciale');

    const shouldDisplay = isRulePageVisible;

    // Fonction pour appliquer la mise en surbrillance
    const highlightKeywords = (content, keywords) => {
        if (!keywords.length) return content;
        const escapedKeywords = keywords.map((kw) => kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
        const regex = new RegExp(`(${escapedKeywords.join('|')})`, 'gi');
        return content.replace(regex, '<span style="background-color: yellow; font-weight: bold;">$1</span>');
    };



    return (
        <Container maxWidth="100vw" sx={{
            displayPrint: 'none',
            display: shouldDisplay ? 'block' : 'none',
            marginTop: 12,
            minHeight: '85vh'
        }}>
            <Typography variant="h4" gutterBottom>
                Règles simplifiées
            </Typography>

            {[
                { group: uniqueKwTable, name: 'kwtable', label: "Table & Décors" },
                { group: uniqueKwGenerique, name: 'kwgenerique', label: "Générique" },
                { group: uniqueKwPhase, name: 'kwphase', label: "Types d'actions" },
                { group: uniqueKwUnite, name: 'kwunite', label: "Unitées" },
                { group: uniqueKwSpeciale, name: 'kwspeciale', label: "Armes & Spéciales" }
            ].map(({ group, name, label }, index) => (
                <Accordion key={index} sx={{ mb: 2 }}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Typography>{label}</Typography>
                    </AccordionSummary>
                    <AccordionDetails>
                        <Box>
                            {group.map((keyword) => (
                                <Chip size="small"
                                    key={keyword}
                                    label={keyword}
                                    onClick={() => handleChipClick(name, keyword)}
                                    color={allSelectedKeywords.includes(keyword) ? "primary" : "default"}
                                    sx={{ m: 0.5 }}
                                />
                            ))}
                        </Box>
                    </AccordionDetails>
                </Accordion>
            ))}

            <Box>
                {filteredRules.map((rule, index) => (
                    <Card key={index} sx={{ mb: 2 }}>
                        <CardContent>
                            <Typography variant="h6">{rule.title1 || rule.titlesup}</Typography>
                            {rule.title2 && (
                                <Typography variant="subtitle1" color="textSecondary">
                                    {rule.title2}
                                </Typography>
                            )}
                            {rule.title3 && (
                                <Typography variant="subtitle1" color="textSecondary">
                                    {rule.title3}
                                </Typography>
                            )}
                            <Typography
                                variant="body2"
                                dangerouslySetInnerHTML={{
                                    __html: highlightKeywords(rule.content, allSelectedKeywords),
                                }}
                            />
                        </CardContent>
                    </Card>
                ))}
            </Box>
        </Container>
    );
}

