import React from 'react';
import { Container, Grid, Accordion, AccordionSummary, AccordionDetails, Card, CardContent, Box, Typography, Divider } from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { useTranslation } from 'react-i18next';

function groupCodexByCategory(jsonData) {
    const groupedCodex = {};
    jsonData.forEach((codex) => {
        const category = codex.categorie || 'Autres';
        if (!groupedCodex[category]) groupedCodex[category] = [];
        groupedCodex[category].push(codex);
    });
    return groupedCodex;
}

export default function CodexSelectionPopup({ codexList = [], onSelectCodex, onClose }) {
    const { t } = useTranslation();
    const groupedCodex = groupCodexByCategory(codexList);

    return (
        <Container
            padding={1}
            sx={{
                marginTop: '70px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexGrow: 1
            }}
        >
            <Grid container spacing={1} paddingTop={1} justifyContent="center">
                {Object.entries(groupedCodex).map(([category, codexList]) => (
                    <Grid key={category} item xs={12} md={3} sx={{ justifyContent: 'center', alignItems: 'center', height: '100%' }}>
                        <Accordion elevation={3}>
                            <AccordionSummary
                                sx={{
                                    backgroundImage: `url(${process.env.PUBLIC_URL + '/' + encodeURIComponent(category) + ".png"})`,
                                    backgroundRepeat: 'no-repeat',
                                    backgroundPosition: 'center',
                                    backgroundSize: 'cover',
                                    width: '100%',
                                    height: '100%',
                                    filter: 'grayscale(100%)',
                                    transition: 'filter 0.3s ease',
                                    "&:hover": { filter: 'grayscale(0%)' }
                                }}
                                expandIcon={<ExpandMoreIcon />}
                            >
                                <Grid container direction="row" justifyContent="center" alignItems="center" marginTop={1} spacing={2}>
                                    <Grid item xs={12} sx={{ minHeight: '100px' }}>
                                        <Typography variant="h4" color="white" align="center"><b>{category.toUpperCase()}</b></Typography>
                                    </Grid>
                                </Grid>
                            </AccordionSummary>

                            <AccordionDetails>
                                <Grid marginTop={1} spacing={2} container direction="row" justifyContent="center" alignItems="center">
                                    {codexList.map((codex) => (
                                        <Grid item xs={6} md={6} key={codex.codex} className="popup-item" onClick={() => onSelectCodex(codex)}>
                                            <Card>
                                                <CardContent variant="outlined" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                                                    <Box
                                                        component="img"
                                                        src={process.env.PUBLIC_URL + '/' + codex.logo}
                                                        alt={codex.codex}
                                                        sx={{
                                                            transition: 'transform 0.3s ease',
                                                            "&:hover": { transform: 'scale(1.1)' },
                                                            maxWidth: '100px',
                                                            maxHeight: '100px',
                                                            width: 'auto',
                                                            height: 'auto'
                                                        }}
                                                    />
                                                    <Typography variant="body2" color="text.secondary" align="center">
                                                        <b>{codex.codex}</b><br /><i>{codex.version}</i>
                                                    </Typography>
                                                </CardContent>
                                            </Card>
                                        </Grid>
                                    ))}
                                </Grid>
                            </AccordionDetails>
                        </Accordion>
                        <Divider />
                    </Grid>
                ))}
            </Grid>
        </Container>
    );
}